/**
 * App component.
 * 
 * Root application component. Sets up the R3F Canvas with
 * proper configuration, overlays the HUD UI, and manages
 * the overall application lifecycle.
 */

import { useMemo, Suspense } from 'react'
import { Canvas } from '@react-three/fiber'
import { SceneManager } from '@/components/scene'
import { FlightDataHUD, StatusBar, LoadingScreen, MissingConfigBanner } from '@/components/ui/hud'
import { validateConfig } from '@/config/keys'

export default function App() {
  const missingKeys = useMemo(() => validateConfig(), [])

  return (
    <div className="w-full h-full relative bg-aviation-dark">
      {/* 3D Scene */}
      <Canvas
        camera={{
          fov: 60,
          near: 10000, // Increase near plane to reduce z-fighting from space
          far: 1e9,
          position: [50000000, 0, 0], // Start viewing from X-axis
          up: [0, 0, 1], // Z-up coordinate system for ECEF
        }}
        gl={{
          antialias: true,
          alpha: false,
          powerPreference: 'high-performance',
          // logarithmicDepthBuffer is incompatible with some post-processing effects
          // and aerial perspective requires linear depth
          logarithmicDepthBuffer: false,
        }}
        style={{ position: 'absolute', inset: 0 }}
      >
        <Suspense fallback={null}>
          <SceneManager />
        </Suspense>
      </Canvas>

      {/* UI Overlay */}
      <FlightDataHUD />
      <StatusBar />
      <LoadingScreen />
      <MissingConfigBanner missingKeys={missingKeys} />
    </div>
  )
}
