/**
 * FlightDataHUD component.
 * 
 * Heads-up display overlay showing essential flight data:
 * speed, altitude, heading, vertical speed, FPS.
 * MSFS/X-Plane style glass-panel aesthetic.
 */

import { memo } from 'react'
import { useAircraftStore, useUIStore } from '@/stores'

export const FlightDataHUD = memo(function FlightDataHUD() {
  const speed = useAircraftStore((s) => s.speed)
  const altitude = useAircraftStore((s) => s.altitude)
  const heading = useAircraftStore((s) => s.heading)
  const verticalSpeed = useAircraftStore((s) => s.verticalSpeed)
  const fps = useUIStore((s) => s.fps)
  const hudVisible = useUIStore((s) => s.hudVisible)

  if (!hudVisible) return null

  return (
    <div className="absolute top-4 left-4 z-10 flex flex-col gap-2">
      {/* Flight Data Panel */}
      <div className="glass-panel p-3 min-w-[200px]">
        <div className="text-xs uppercase tracking-widest text-aviation-blue/70 mb-2 font-instrument">
          Flight Data
        </div>
        <div className="grid grid-cols-2 gap-x-4 gap-y-1">
          <DataRow label="SPD" value={`${Math.round(speed)}`} unit="KTS" />
          <DataRow label="ALT" value={`${Math.round(altitude)}`} unit="FT" />
          <DataRow label="HDG" value={`${Math.round(heading).toString().padStart(3, '0')}`} unit="°" />
          <DataRow label="VS" value={`${verticalSpeed >= 0 ? '+' : ''}${Math.round(verticalSpeed)}`} unit="FPM" />
        </div>
      </div>

      {/* FPS Counter */}
      <div className="glass-panel px-3 py-1.5 text-xs">
        <span className="text-aviation-green/80 font-mono tabular-nums">
          {fps} FPS
        </span>
      </div>
    </div>
  )
})

interface DataRowProps {
  label: string
  value: string
  unit: string
}

function DataRow({ label, value, unit }: DataRowProps) {
  return (
    <div className="flex items-baseline gap-1">
      <span className="text-[10px] uppercase tracking-wider text-aviation-blue/50 w-8">
        {label}
      </span>
      <span className="text-sm font-instrument font-semibold text-white tabular-nums">
        {value}
      </span>
      <span className="text-[9px] text-white/40">{unit}</span>
    </div>
  )
}
