/**
 * SceneManager component.
 * 
 * Orchestrates all R3F scene components and hooks.
 * Must be rendered inside a Canvas component.
 * Handles initialization and loading state.
 */

import { useEffect } from 'react'
import { useThree } from '@react-three/fiber'
import { AtmosphereScene } from './AtmosphereScene'
import { Tiles3D } from './Tiles3D'
import { Globe } from './Globe'
import { CameraController } from './CameraController'
import { useFPS, useSimulation } from '@/hooks'
import { useUIStore } from '@/stores'

export function SceneManager() {
  const { gl } = useThree()
  const setIsLoading = useUIStore((s) => s.setIsLoading)
  const setLoadingMessage = useUIStore((s) => s.setLoadingMessage)

  // Initialize hooks
  useFPS()
  useSimulation()

  // Mark loading complete after renderer is ready
  useEffect(() => {
    setLoadingMessage('Renderer ready')
    // Give atmosphere textures a moment to generate
    const timer = setTimeout(() => {
      setIsLoading(false)
    }, 2000)
    return () => clearTimeout(timer)
  }, [gl, setIsLoading, setLoadingMessage])

  return (
    <>
      <CameraController />
      <AtmosphereScene>
        <Tiles3D />
        {/* <Globe /> */}
      </AtmosphereScene>
    </>
  )
}
