/**
 * Aircraft state store.
 * Manages position, orientation, speed, and systems state.
 * Position is in ECEF coordinates (meters).
 */

import { create } from 'zustand'

export interface AircraftState {
  /** ECEF position [x, y, z] in meters */
  position: [number, number, number]
  /** Euler rotation [pitch, yaw, roll] in radians */
  rotation: [number, number, number]
  /** Speed in knots */
  speed: number
  /** Altitude in feet MSL */
  altitude: number
  /** Heading in degrees (0-360) */
  heading: number
  /** Vertical speed in feet per minute */
  verticalSpeed: number
  /** Whether the aircraft is on the ground */
  isOnGround: boolean

  // Actions
  setPosition: (pos: [number, number, number]) => void
  setRotation: (rot: [number, number, number]) => void
  setSpeed: (speed: number) => void
  setAltitude: (alt: number) => void
  setHeading: (hdg: number) => void
  setVerticalSpeed: (vs: number) => void
  setIsOnGround: (grounded: boolean) => void
}

// Default position: San Francisco International Airport (SFO)
// Approximate ECEF coordinates for 37.6213° N, 122.3790° W
const DEFAULT_LAT = 37.6213
const DEFAULT_LON = -122.379
const DEFAULT_ALT = 10000 // feet

// Convert geodetic to ECEF (simplified)
function geodeticToECEF(
  latDeg: number,
  lonDeg: number,
  altMeters: number
): [number, number, number] {
  const a = 6378137.0 // WGS84 semi-major axis
  const lat = (latDeg * Math.PI) / 180
  const lon = (lonDeg * Math.PI) / 180
  const N = a // simplified, ignoring flattening
  const x = (N + altMeters) * Math.cos(lat) * Math.cos(lon)
  const y = (N + altMeters) * Math.cos(lat) * Math.sin(lon)
  const z = (N + altMeters) * Math.sin(lat)
  return [x, y, z]
}

const defaultPosition = geodeticToECEF(
  DEFAULT_LAT,
  DEFAULT_LON,
  DEFAULT_ALT * 0.3048 // feet to meters
)

export const useAircraftStore = create<AircraftState>((set) => ({
  position: defaultPosition,
  rotation: [0, 0, 0],
  speed: 250,
  altitude: DEFAULT_ALT,
  heading: 280,
  verticalSpeed: 0,
  isOnGround: false,

  setPosition: (position) => set({ position }),
  setRotation: (rotation) => set({ rotation }),
  setSpeed: (speed) => set({ speed }),
  setAltitude: (altitude) => set({ altitude }),
  setHeading: (heading) => set({ heading }),
  setVerticalSpeed: (verticalSpeed) => set({ verticalSpeed }),
  setIsOnGround: (isOnGround) => set({ isOnGround }),
}))
