/**
 * LoadingScreen component.
 * 
 * Full-screen loading overlay shown during initialization.
 * Features aviation-style aesthetics with progress indication.
 */

import { memo } from 'react'
import { useUIStore } from '@/stores'

export const LoadingScreen = memo(function LoadingScreen() {
  const isLoading = useUIStore((s) => s.isLoading)
  const loadingMessage = useUIStore((s) => s.loadingMessage)

  if (!isLoading) return null

  return (
    <div className="fixed inset-0 z-50 bg-aviation-dark flex flex-col items-center justify-center">
      {/* Logo / Title */}
      <div className="mb-8 text-center">
        <h1 className="text-4xl font-instrument font-bold tracking-[0.3em] text-white mb-2">
          FLIGHTSIM
        </h1>
        <div className="text-sm tracking-[0.5em] text-aviation-blue/60 uppercase">
          Version 7
        </div>
      </div>

      {/* Loading spinner */}
      <div className="relative w-16 h-16 mb-6">
        <div className="absolute inset-0 border-2 border-aviation-blue/20 rounded-full" />
        <div className="absolute inset-0 border-2 border-transparent border-t-aviation-blue rounded-full animate-spin" />
      </div>

      {/* Loading message */}
      <div className="text-xs tracking-wider text-white/40 uppercase">
        {loadingMessage}
      </div>
    </div>
  )
})
