/**
 * AtmosphereScene component.
 * 
 * Wraps @takram/three-atmosphere R3F components to render
 * realistic atmospheric scattering, sky, stars, and lighting.
 * Uses the light-source lighting approach for compatibility with 3D tiles.
 * 
 * - Atmosphere: Renders sky and aerial perspective
 * - SunLight: Provides directional lighting for 3D tiles (follows camera)
 * - SkyLight: Provides indirect sky lighting (follows camera)
 * - Stars: Renders stars at infinite distance
 */

import { useRef, useMemo } from 'react'
import { useFrame, useThree, useLoader } from '@react-three/fiber'
import { EffectComposer } from '@react-three/postprocessing'
import { Vector3 } from 'three'
import {
  Atmosphere,
  Sky,
  Stars,
  SunLight,
  SkyLight,
  AerialPerspective,
  type AtmosphereApi,
} from '@takram/three-atmosphere/r3f'
import { 
  DEFAULT_PRECOMPUTED_TEXTURES_URL, 
  PrecomputedTexturesLoader 
} from '@takram/three-atmosphere'
import { useSimulationStore } from '@/stores'

export function AtmosphereScene({ children }: { children?: React.ReactNode }) {
  const atmosphereRef = useRef<AtmosphereApi>(null)
  const sunLightRef = useRef<any>(null)
  const skyLightRef = useRef<any>(null)
  
  const { camera, gl } = useThree()
  
  // Load textures using standard R3F pattern
  // R3F instantiates the loader and passes it to the callback for configuration
  const textures = useLoader(
    PrecomputedTexturesLoader,
    DEFAULT_PRECOMPUTED_TEXTURES_URL,
    (loader: PrecomputedTexturesLoader) => {
      loader.setType(gl)
    }
  )
  
  const atmosphereEnabled = useSimulationStore((s) => s.atmosphereEnabled)
  const starsVisible = useSimulationStore((s) => s.starsVisible)
  const useRealTime = useSimulationStore((s) => s.useRealTime)
  const dateTime = useSimulationStore((s) => s.dateTime)

  // Use a mutable vector for position updates to avoid GC
  const cameraPosition = useMemo(() => new Vector3(), [])

  useFrame(() => {
    // Only update ref if loaded
    if (atmosphereRef.current) {
      if (useRealTime) {
        atmosphereRef.current.updateByDate(new Date())
      } else {
        // Use a fixed date (noon UTC) by default to ensure daylight
        atmosphereRef.current.updateByDate(new Date('2024-06-21T12:00:00Z'))
      }
    }

    // Update lights to follow camera (so lighting is calculated for viewer's location)
    // 3D tiles are PBR and need light sources near the camera for correct specularity/shadows
    camera.getWorldPosition(cameraPosition)
    if (sunLightRef.current) {
      sunLightRef.current.position.copy(cameraPosition)
    }
    if (skyLightRef.current) {
      skyLightRef.current.position.copy(cameraPosition)
    }
  })

  if (!atmosphereEnabled) return <>{children}</>

  return (
    <Atmosphere ref={atmosphereRef} correctAltitude={true} textures={textures}>
      {children}
      <ambientLight intensity={0.5} />
      <Sky />
      {starsVisible && <Stars />}
      
      {/* Light sources for PBR materials (3D Tiles) */}
      <SunLight ref={sunLightRef} />
      <SkyLight ref={skyLightRef} />

      {/* Post-processing for atmosphere haze only (no lighting override) */}
      {/* enableNormalPass is required for correct aerial perspective depth cues */}
      {/* multisampling=0 prevents depth buffer issues in some post-processing chains */}
      <EffectComposer enableNormalPass multisampling={0}>
        <AerialPerspective />
      </EffectComposer>
    </Atmosphere>
  )
}
