/**
 * UI state store.
 * Manages panel visibility, selected tools, and modal state.
 */

import { create } from 'zustand'

export interface UIState {
  /** Whether the HUD is visible */
  hudVisible: boolean
  /** Whether the PFD panel is visible */
  pfdVisible: boolean
  /** Whether the ND panel is visible */
  ndVisible: boolean
  /** Whether the MFD panel is visible */
  mfdVisible: boolean
  /** Whether the settings panel is open */
  settingsOpen: boolean
  /** Whether the loading screen is shown */
  isLoading: boolean
  /** Loading progress message */
  loadingMessage: string
  /** FPS counter value */
  fps: number

  // Actions
  toggleHud: () => void
  togglePfd: () => void
  toggleNd: () => void
  toggleMfd: () => void
  setSettingsOpen: (open: boolean) => void
  setIsLoading: (loading: boolean) => void
  setLoadingMessage: (message: string) => void
  setFps: (fps: number) => void
}

export const useUIStore = create<UIState>((set) => ({
  hudVisible: true,
  pfdVisible: true,
  ndVisible: false,
  mfdVisible: false,
  settingsOpen: false,
  isLoading: true,
  loadingMessage: 'Initializing...',
  fps: 0,

  toggleHud: () => set((s) => ({ hudVisible: !s.hudVisible })),
  togglePfd: () => set((s) => ({ pfdVisible: !s.pfdVisible })),
  toggleNd: () => set((s) => ({ ndVisible: !s.ndVisible })),
  toggleMfd: () => set((s) => ({ mfdVisible: !s.mfdVisible })),
  setSettingsOpen: (settingsOpen) => set({ settingsOpen }),
  setIsLoading: (isLoading) => set({ isLoading }),
  setLoadingMessage: (loadingMessage) => set({ loadingMessage }),
  setFps: (fps) => set({ fps }),
}))
