/**
 * Camera state store.
 * Manages camera mode, target, and follow behavior.
 */

import { create } from 'zustand'

export type CameraMode = 'orbit' | 'follow' | 'cockpit' | 'free'

export interface CameraState {
  /** Current camera mode */
  mode: CameraMode
  /** Camera distance from target (for orbit/follow modes) */
  distance: number
  /** Field of view in degrees */
  fov: number
  /** Whether camera auto-rotates */
  autoRotate: boolean
  /** Camera look-at target offset [x, y, z] */
  targetOffset: [number, number, number]

  // Actions
  setMode: (mode: CameraMode) => void
  setDistance: (distance: number) => void
  setFov: (fov: number) => void
  setAutoRotate: (autoRotate: boolean) => void
  setTargetOffset: (offset: [number, number, number]) => void
}

export const useCameraStore = create<CameraState>((set) => ({
  mode: 'orbit',
  distance: 50000000, // Start zoomed out to see Earth
  fov: 60,
  autoRotate: false,
  targetOffset: [0, 0, 0],

  setMode: (mode) => set({ mode }),
  setDistance: (distance) => set({ distance }),
  setFov: (fov) => set({ fov }),
  setAutoRotate: (autoRotate) => set({ autoRotate }),
  setTargetOffset: (targetOffset) => set({ targetOffset }),
}))
