/**
 * useSimulation hook.
 * 
 * Manages the simulation clock and updates real-time date.
 * Call from within an R3F Canvas component.
 */

import { useFrame } from '@react-three/fiber'
import { useSimulationStore } from '@/stores'

export function useSimulation() {
  const isRunning = useSimulationStore((s) => s.isRunning)
  const useRealTime = useSimulationStore((s) => s.useRealTime)
  const setDateTime = useSimulationStore((s) => s.setDateTime)

  useFrame(() => {
    if (!isRunning) return

    if (useRealTime) {
      setDateTime(new Date())
    }
    // Future: advance simulation time by delta * timeScale
  })
}
