/**
 * Application configuration and API key management.
 * Validates environment variables at startup.
 */

export const config = {
  cesiumIonToken: import.meta.env.VITE_CESIUM_ION_TOKEN as string,
  cesiumAssetId: '2275207', // Google Photorealistic 3D Tiles
} as const

/**
 * Validates that required API keys are configured.
 * Returns an array of missing key names.
 */
export function validateConfig(): string[] {
  const missing: string[] = []

  if (
    !config.cesiumIonToken ||
    config.cesiumIonToken === 'your_cesium_ion_token_here'
  ) {
    missing.push('VITE_CESIUM_ION_TOKEN')
  }

  return missing
}
