/**
 * CameraController component.
 * 
 * Manages camera behavior based on the current camera mode.
 * Supports orbit, follow, cockpit, and free camera modes.
 * Uses drei's OrbitControls for orbit mode.
 */

import { useRef, useEffect } from 'react'
import { useThree, useFrame } from '@react-three/fiber'
import { OrbitControls } from '@react-three/drei'
import type { OrbitControls as OrbitControlsImpl } from 'three-stdlib'
import { useCameraStore } from '@/stores'

export function CameraController() {
  const controlsRef = useRef<OrbitControlsImpl>(null)
  const { camera } = useThree()
  const mode = useCameraStore((s) => s.mode)
  const distance = useCameraStore((s) => s.distance)
  const fov = useCameraStore((s) => s.fov)

  useEffect(() => {
    if (camera) {
      // Force Z-up for ECEF coordinate system
      camera.up.set(0, 0, 1)
      if ('updateProjectionMatrix' in camera) {
        ;(camera as THREE.PerspectiveCamera).updateProjectionMatrix()
      }
    }
  }, [camera])

  if (mode === 'orbit' || mode === 'free') {
    return (
      <OrbitControls
        ref={controlsRef}
        enableDamping
        dampingFactor={0.05}
        minDistance={100}
        maxDistance={200000000}
        enablePan
        zoomSpeed={1.2}
        rotateSpeed={0.5}
        target={[0, 0, 0]} // Always orbit around Earth center initially
      />
    )
  }

  return null
}

// Need THREE namespace for PerspectiveCamera type
import type * as THREE from 'three'
