/**
 * Simulation state store.
 * Manages time, weather, and physics simulation controls.
 */

import { create } from 'zustand'

export interface SimulationState {
  /** Whether the simulation is running */
  isRunning: boolean
  /** Simulation time multiplier (1 = real-time) */
  timeScale: number
  /** Current simulation date/time */
  dateTime: Date
  /** Whether to use real-time clock */
  useRealTime: boolean
  /** Whether atmosphere rendering is enabled */
  atmosphereEnabled: boolean
  /** Whether 3D tiles are enabled */
  tilesEnabled: boolean
  /** Whether stars are visible */
  starsVisible: boolean

  // Actions
  setIsRunning: (running: boolean) => void
  setTimeScale: (scale: number) => void
  setDateTime: (date: Date) => void
  setUseRealTime: (useReal: boolean) => void
  setAtmosphereEnabled: (enabled: boolean) => void
  setTilesEnabled: (enabled: boolean) => void
  setStarsVisible: (visible: boolean) => void
  togglePause: () => void
}

export const useSimulationStore = create<SimulationState>((set) => ({
  isRunning: true,
  timeScale: 1,
  dateTime: new Date(),
  useRealTime: false, // Default to fixed time (noon) to ensure visibility
  atmosphereEnabled: true,
  tilesEnabled: true,
  starsVisible: true,

  setIsRunning: (isRunning) => set({ isRunning }),
  setTimeScale: (timeScale) => set({ timeScale }),
  setDateTime: (dateTime) => set({ dateTime }),
  setUseRealTime: (useRealTime) => set({ useRealTime }),
  setAtmosphereEnabled: (atmosphereEnabled) => set({ atmosphereEnabled }),
  setTilesEnabled: (tilesEnabled) => set({ tilesEnabled }),
  setStarsVisible: (starsVisible) => set({ starsVisible }),
  togglePause: () => set((s) => ({ isRunning: !s.isRunning })),
}))
