/**
 * MissingConfigBanner component.
 * 
 * Shown when required API keys are not configured.
 * Provides instructions for setup.
 */

import { memo } from 'react'

interface MissingConfigBannerProps {
  missingKeys: string[]
}

export const MissingConfigBanner = memo(function MissingConfigBanner({
  missingKeys,
}: MissingConfigBannerProps) {
  if (missingKeys.length === 0) return null

  return (
    <div className="absolute top-4 right-4 z-20 glass-panel p-4 max-w-sm">
      <div className="flex items-center gap-2 mb-2">
        <span className="w-2 h-2 rounded-full bg-aviation-yellow animate-pulse" />
        <span className="text-xs uppercase tracking-wider text-aviation-yellow font-instrument">
          Configuration Required
        </span>
      </div>
      <div className="text-xs text-white/60 space-y-1">
        <p>The following environment variables are missing:</p>
        <ul className="list-disc list-inside text-aviation-orange/80">
          {missingKeys.map((key) => (
            <li key={key} className="font-mono text-[10px]">{key}</li>
          ))}
        </ul>
        <p className="mt-2 text-white/40">
          Copy <code className="text-aviation-blue/60">.env.example</code> to{' '}
          <code className="text-aviation-blue/60">.env</code> and fill in your keys.
        </p>
      </div>
    </div>
  )
})
