/**
 * StatusBar component.
 * 
 * Bottom status bar showing simulation status, time, and quick controls.
 */

import { memo, useCallback } from 'react'
import { useSimulationStore, useUIStore, useCameraStore } from '@/stores'

export const StatusBar = memo(function StatusBar() {
  const isRunning = useSimulationStore((s) => s.isRunning)
  const togglePause = useSimulationStore((s) => s.togglePause)
  const atmosphereEnabled = useSimulationStore((s) => s.atmosphereEnabled)
  const setAtmosphereEnabled = useSimulationStore((s) => s.setAtmosphereEnabled)
  const tilesEnabled = useSimulationStore((s) => s.tilesEnabled)
  const setTilesEnabled = useSimulationStore((s) => s.setTilesEnabled)
  const cameraMode = useCameraStore((s) => s.mode)
  const loadingMessage = useUIStore((s) => s.loadingMessage)

  const toggleAtmosphere = useCallback(() => {
    setAtmosphereEnabled(!atmosphereEnabled)
  }, [atmosphereEnabled, setAtmosphereEnabled])

  const toggleTiles = useCallback(() => {
    setTilesEnabled(!tilesEnabled)
  }, [tilesEnabled, setTilesEnabled])

  return (
    <div className="absolute bottom-0 left-0 right-0 z-10">
      <div className="glass-panel mx-4 mb-4 px-4 py-2 flex items-center justify-between text-xs">
        {/* Left: Status */}
        <div className="flex items-center gap-4">
          <button
            onClick={togglePause}
            className="flex items-center gap-1.5 hover:text-aviation-orange transition-colors"
          >
            <span
              className={`w-2 h-2 rounded-full ${
                isRunning ? 'bg-aviation-green' : 'bg-aviation-yellow'
              }`}
            />
            {isRunning ? 'RUNNING' : 'PAUSED'}
          </button>

          <span className="text-white/30">|</span>
          <span className="text-white/50 uppercase">CAM: {cameraMode}</span>
        </div>

        {/* Center: Loading message */}
        {loadingMessage && (
          <div className="text-aviation-blue/70 animate-pulse">
            {loadingMessage}
          </div>
        )}

        {/* Right: Quick toggles */}
        <div className="flex items-center gap-3">
          <ToggleButton
            label="ATM"
            active={atmosphereEnabled}
            onClick={toggleAtmosphere}
          />
          <ToggleButton
            label="3DT"
            active={tilesEnabled}
            onClick={toggleTiles}
          />
          <span className="text-white/30">|</span>
          <span className="text-white/40">
            {new Date().toLocaleTimeString('en-US', { hour12: false })} UTC
          </span>
        </div>
      </div>
    </div>
  )
})

interface ToggleButtonProps {
  label: string
  active: boolean
  onClick: () => void
}

function ToggleButton({ label, active, onClick }: ToggleButtonProps) {
  return (
    <button
      onClick={onClick}
      className={`px-2 py-0.5 rounded text-[10px] uppercase tracking-wider transition-colors border ${
        active
          ? 'border-aviation-green/40 text-aviation-green bg-aviation-green/10'
          : 'border-white/10 text-white/30 bg-transparent'
      }`}
    >
      {label}
    </button>
  )
}
