/**
 * Tiles3D component.
 * 
 * Renders Google Photorealistic 3D Tiles via Cesium Ion proxy.
 * Uses 3d-tiles-renderer with CesiumIonAuthPlugin for authentication.
 * Manages tile loading lifecycle within R3F.
 */

import { useEffect, useRef } from 'react'
import { useThree, useFrame } from '@react-three/fiber'
import { TilesRenderer } from '3d-tiles-renderer'
import { CesiumIonAuthPlugin } from '3d-tiles-renderer/core/plugins'
import { config } from '@/config/keys'
import { useSimulationStore, useUIStore } from '@/stores'

export function Tiles3D() {
  const { camera, scene, gl } = useThree()
  const tilesRef = useRef<TilesRenderer | null>(null)
  const tilesEnabled = useSimulationStore((s) => s.tilesEnabled)
  const setLoadingMessage = useUIStore((s) => s.setLoadingMessage)

  useEffect(() => {
    if (!tilesEnabled) return
    if (
      !config.cesiumIonToken ||
      config.cesiumIonToken === 'your_cesium_ion_token_here'
    ) {
      console.warn(
        'Cesium Ion token not configured. 3D tiles will not load. Set VITE_CESIUM_ION_TOKEN in .env'
      )
      return
    }

    const tiles = new TilesRenderer()

    // Register Cesium Ion auth for Google Photorealistic 3D Tiles
    tiles.registerPlugin(
      new CesiumIonAuthPlugin({
        apiToken: config.cesiumIonToken,
        assetId: config.cesiumAssetId,
        autoRefreshToken: true,
      })
    )

    // Configure for performance
    tiles.errorTarget = 6
    tiles.maxDepth = 15

    // Set camera and resolution
    tiles.setCamera(camera)
    tiles.setResolutionFromRenderer(camera, gl)

    // Event listeners
    tiles.addEventListener('load-tileset', (e: any) => {
      console.log('Loaded tileset:', e.tileset)
      setLoadingMessage('Loading 3D tiles...')
    })
    tiles.addEventListener('load-error', (e: any) => {
      console.error('Tile load error:', e.error, e.url)
    })
    tiles.addEventListener('tiles-load-end', () => {
      console.log('Tiles loaded')
      setLoadingMessage('')
    })

    // Add to scene
    scene.add(tiles.group)
    tilesRef.current = tiles

    return () => {
      scene.remove(tiles.group)
      tiles.dispose()
      tilesRef.current = null
    }
  }, [tilesEnabled, camera, scene, gl, setLoadingMessage])

  useFrame(() => {
    const tiles = tilesRef.current
    if (!tiles) return

    camera.updateMatrixWorld()
    tiles.setResolutionFromRenderer(camera, gl)
    tiles.update()
  })

  return null
}
